-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9182, 23, 'Soziales und emotionales Lernen im Unterricht verankern (Land)', 'Meta-Analysen zu schulischem sozial-emotionalem Lernen zeigen besseres Klassenklima und weniger Mobbing; ohne festes Programm, Zeitbudget und geschulte Lehrkräfte hängt die Wirkung stark von der Umsetzung ab.', 'belegt', 'https://www.future-ed.org/parsing-the-evidence-on-social-emotional-learnings-impact/', 'land', null, true, 'blind'),
  (9183, 23, 'Präventionsprogramme gegen Mobbing und Gewalt an Schulen ausbauen und verstetigen (Land)', 'Schulische Anti-Mobbing-Programme senken Mobbing laut Meta-Analysen um rund 20 Prozent, intensive Programme stärker; die Vorschläge nennen meist kein bestimmtes, erprobtes Programm, Wirkung hängt von Auswahl und Umfang ab.', 'belegt', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/school-based-programs-reduce-bullying-and-victimization', 'land', null, true, 'blind'),
  (9184, 23, 'Klassenrat und Mitbestimmungsgremien der Schülerschaft stärken (Land)', 'Regelmäßige Klassenräte können Konflikte früh sichtbar machen und Klassennormen beeinflussen; die Wirkung auf Mobbing ist kaum untersucht, der Schwerpunkt liegt auf Beteiligung. Günstig und rasch einführbar.', 'offen', null, 'land', null, true, 'blind'),
  (9185, 23, 'Schulsozialarbeit und Schulpsychologie an Schulen ausbauen (Land)', 'Fachkräfte vor Ort können bei Konflikten und Mobbing eingreifen und Lehrkräfte entlasten; belastbare Wirkungsstudien zu Mobbing fehlen weitgehend, und Fachkräftemangel sowie Finanzierung bremsen den Ausbau.', 'offen', null, 'land', null, true, 'blind'),
  (9186, 23, 'Unabhängige Beschwerde- und Ombudsstellen für Mobbing und Diskriminierung an Schulen (Land)', 'Eine Stelle außerhalb der Schule gibt Betroffenen einen Weg, wenn die Schule nicht handelt; sie greift meist erst spät ein, Wirkungsbelege auf Mobbing fehlen. Rechtlich einfach und mit wenig Personal einrichtbar.', 'offen', null, 'land', null, true, 'blind'),
  (9187, 23, 'Fortbildung von Lehrkräften zum Umgang mit Mobbing, Übergriffen und Diskriminierung (Land)', 'Eine Meta-Analyse findet, dass Programme mit Lehrkräfte-Bausteinen deren Eingreifen spürbar verbessern; kurze Schulungen allein zeigten in einer Studie keine Wirkung. Fortbildungszeit und Vertretung müssen organisiert werden.', 'gemischt', 'https://dare.uva.nl/id/b26d9daf-c6d9-4aa1-95e1-ae168727717f', 'land', null, true, 'blind'),
  (9188, 23, 'Schulische Ordnungsmaßnahmen verschärfen und Schulverweise beschleunigen (Land)', 'Konsequente Regeln sind in wirksamen Programmen ein Baustein; harte Ausschlüsse allein ändern Klassennormen kaum und verlagern das Problem. Ordnungsrecht ist Landessache, Spezialschulen brauchen Plätze und Personal.', 'gemischt', 'https://www.ojp.gov/index%2Ephp/ncjrs/virtual-library/abstracts/effectiveness-school-based-programs-reduce-bullying-systematic-and', 'land', null, true, 'blind'),
  (9189, 23, 'Ziffern- und Kopfnoten durch schriftliche oder mündliche Rückmeldungen ersetzen (Land)', 'Weniger Noten kann Bewertungsdruck senken; Studien finden teils weniger Angst, teils kehrt sie zurück, weil Abschlüsse und Übergänge weiter Noten verlangen. Änderung der Schulordnung möglich, verlangt aber Schulung.', 'gemischt', 'https://www.timeshighereducation.com/news/gradeless-learning-fails-improve-student-well-being', 'land', null, true, 'blind'),
  (9190, 23, 'Übergang auf weiterführende Schulen weniger leistungsabhängig gestalten (Land)', 'Der Übertritt gilt als belastende Phase; weniger Auslese kann den Druck in den Klassen 4 bis 6 senken. Ob Stress messbar sinkt, ist kaum untersucht. Landesrecht, rasch änderbar.', 'offen', null, 'land', null, true, 'blind'),
  (9191, 23, 'Resilienzförderung und Stressprävention in Rahmenplänen und Unterricht verankern (Land)', 'Schulische Programme senken Angst und depressive Beschwerden laut Meta-Analysen kurzfristig, die Wirkung lässt aber nach; sie stärken den Umgang mit Druck, senken den Druck selbst nicht. Lehrplanänderung leicht umsetzbar.', 'gemischt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7548227', 'land', null, true, 'blind'),
  (9192, 23, 'Jugendschutz auf Plattformen stärker durchsetzen, etwa mit Altersverifikation (Bund)', 'Löschpflichten und Altersprüfung können Angriffe auf Kinder erschweren; Cybermobbing unter Mitschülern läuft oft über legale Inhalte und Messenger, Wirkung kaum untersucht. Rahmen setzt das EU-Recht, die Durchsetzung ist national.', 'offen', null, 'bund', null, true, 'blind')
