insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (9193, 23, 11, null, 'Ausreichender Kinder- und Jugendschutz im Internet, auch auf Sozialen Medien; bei der Umsetzung des Digital Services Act Schwerpunkt auf Jugend- und Medienschutz.', '{2303}', 9192, 1, 2, null, 'Löschpflichten und Altersprüfung können Angriffe auf Kinder erschweren; Cybermobbing unter Mitschülern läuft oft über legale Inhalte und Messenger, Wirkung kaum untersucht. Rahmen setzt das EU-Recht, die Durchsetzung ist national.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=41', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9194, 23, 11, 'BE', 'Landesprogramm für psychische Gesundheit an Schulen, mehr schulpsychologische Angebote sowie Prävention, frühe Hilfen und Resilienzförderung im Schulalltag.', '{2304}', null, 1, 2, null, 'Mehr Schulpsychologie und Prävention fangen Belastungen früher auf; Schulprogramme wirken laut Meta-Analysen klein und kurzzeitig und senken den Druck selbst nicht. Zusätzliche Stellen brauchen Fachkräfte und Geld.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=61', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7548227', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9195, 23, 11, 'BE', 'Landesstrategie gegen Gewalt an Schulen, die Prävention, Intervention und Repression verbindet, mit klaren Regeln und konsequentem Handeln.', '{2301,2302}', null, 1, 3, null, 'Eine Strategie auf Datengrundlage kann Prävention und Eingreifen bündeln; welche Maßnahmen folgen, bleibt offen, daher ist die Wirkung nicht abschätzbar. Als Landesstrategie leicht umsetzbar.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=60', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9196, 23, 12, null, 'Plattformbetreiber müssen illegale Inhalte entfernen; der Jugendschutz im Netz wird gestärkt, etwa durch Altersverifikation.', '{2303}', 9192, 1, 2, null, 'Löschpflichten und Altersprüfung können Angriffe auf Kinder erschweren; Cybermobbing unter Mitschülern läuft oft über legale Inhalte und Messenger, Wirkung kaum untersucht. Rahmen setzt das EU-Recht, die Durchsetzung ist national.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9197, 23, 12, 'BE', 'Jede Schule bekommt ein Anti-Mobbing-Team.', '{2302}', null, 2, 2, null, 'Feste Teams, die Mobbingfälle bearbeiten, sind Teil erprobter Schulprogramme; als Einzelmaßnahme ist ihre Wirkung kaum untersucht. Jede Schule braucht dafür geschultes Personal und Zeit.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9198, 23, 12, 'BE', 'Multiprofessionelle Teams an Schulen ausbauen, mit mehr Stellen für Schulsozialarbeit und Schulpsychologie.', '{2302}', 9185, 2, 2, null, 'Fachkräfte vor Ort können bei Konflikten und Mobbing eingreifen und Lehrkräfte entlasten; belastbare Wirkungsstudien zu Mobbing fehlen weitgehend, und Fachkräftemangel sowie Finanzierung bremsen den Ausbau.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9199, 23, 12, 'BE', 'Unabhängige Beschwerdestelle für Schulen und Kitas beim Parlament.', '{2302}', 9186, 1, 3, null, 'Eine Stelle außerhalb der Schule gibt Betroffenen einen Weg, wenn die Schule nicht handelt; sie greift meist erst spät ein, Wirkungsbelege auf Mobbing fehlen. Rechtlich einfach und mit wenig Personal einrichtbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9200, 23, 12, 'BE', 'Wöchentlicher Klassenrat und Schülervertretungen für Konfliktlösung stärken.', '{2301}', 9184, 1, 3, null, 'Regelmäßige Klassenräte können Konflikte früh sichtbar machen und Klassennormen beeinflussen; die Wirkung auf Mobbing ist kaum untersucht, der Schwerpunkt liegt auf Beteiligung. Günstig und rasch einführbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9201, 23, 12, 'BE', 'Wahlpflichtfach Empathie einführen.', '{2301}', 9182, 2, 2, null, 'Meta-Analysen zu schulischem sozial-emotionalem Lernen zeigen besseres Klassenklima und weniger Mobbing; ohne festes Programm, Zeitbudget und geschulte Lehrkräfte hängt die Wirkung stark von der Umsetzung ab.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://www.future-ed.org/parsing-the-evidence-on-social-emotional-learnings-impact/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9202, 23, 12, 'MV', 'Präventionsangebote gegen Mobbing, Cybermobbing, Gewalt und Ausgrenzung weiter unterstützen', '{2301}', 9183, 2, 2, null, 'Schulische Anti-Mobbing-Programme senken Mobbing laut Meta-Analysen um rund 20 Prozent, intensive Programme stärker; die Vorschläge nennen meist kein bestimmtes, erprobtes Programm, Wirkung hängt von Auswahl und Umfang ab.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=36', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/school-based-programs-reduce-bullying-and-victimization', 'belegt', '2026-10-08', false, true, 'blind'),
  (9203, 23, 12, 'MV', 'Leistungsbewertung reformieren, lernförderliche und prozessorientierte Rückmeldungen in den Mittelpunkt stellen', '{2304}', 9189, 1, 2, null, 'Weniger Noten kann Bewertungsdruck senken; Studien finden teils weniger Angst, teils kehrt sie zurück, weil Abschlüsse und Übergänge weiter Noten verlangen. Änderung der Schulordnung möglich, verlangt aber Schulung.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=68', 'https://www.timeshighereducation.com/news/gradeless-learning-fails-improve-student-well-being', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9204, 23, 12, 'ST', 'Ausbildung zur Beratungslehrkraft wird neu aufgelegt.', '{2302}', 9187, 2, 2, null, 'Eine Meta-Analyse findet, dass Programme mit Lehrkräfte-Bausteinen deren Eingreifen spürbar verbessern; kurze Schulungen allein zeigten in einer Studie keine Wirkung. Fortbildungszeit und Vertretung müssen organisiert werden.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', 'https://dare.uva.nl/id/b26d9daf-c6d9-4aa1-95e1-ae168727717f', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9205, 23, 12, 'ST', 'Schulen und andere Einrichtungen müssen verbindlich Schutzkonzepte gegen Gewalt und Diskriminierung entwickeln; Fachkräfte werden verbindlich geschult.', '{2301,2302}', null, 1, 2, null, 'Schutzkonzepte legen Ansprechpersonen, Beschwerdewege und Abläufe fest; ihre Wirkung auf Mobbing unter Schülern ist kaum untersucht und hängt von der Umsetzung ab. Verpflichtung leicht, Umsetzung an allen Schulen aufwendig.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=32', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9206, 23, 13, null, 'Mental Health Coaches mit Gruppenangeboten an weiterführenden Schulen als Anlaufstellen für psychische Belastung ausbauen, Schwerpunkt auf Schulen mit besonderen Bedarfen.', '{2304}', null, 1, 3, null, 'Die Coaches werden laut Evaluation gut angenommen; Wirkungen auf Belastung sind nicht gemessen, und sie lindern Folgen statt den Druck zu senken. Der Bund finanziert das Programm bereits.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=85', 'https://www.bmbfsfj.bund.de/bmbfsfj/aktuelles/pressemitteilungen/bestnoten-fuer-mental-health-coaches-254782', 'offen', '2026-10-08', false, true, 'blind'),
  (9207, 23, 13, null, 'Kinder und Jugendliche besser vor Risiken exzessiver Social-Media-Nutzung schützen, manipulative Algorithmen strenger regulieren.', '{2303}', 9192, 1, 2, null, 'Löschpflichten und Altersprüfung können Angriffe auf Kinder erschweren; Cybermobbing unter Mitschülern läuft oft über legale Inhalte und Messenger, Wirkung kaum untersucht. Rahmen setzt das EU-Recht, die Durchsetzung ist national.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=85', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9208, 23, 13, 'BE', 'Unabhängige Beschwerdestelle gegen Diskriminierung an Schulen unter dem Dach der Ombudsstelle des Landesantidiskriminierungsgesetzes.', '{2302}', 9186, 1, 3, null, 'Eine Stelle außerhalb der Schule gibt Betroffenen einen Weg, wenn die Schule nicht handelt; sie greift meist erst spät ein, Wirkungsbelege auf Mobbing fehlen. Rechtlich einfach und mit wenig Personal einrichtbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=136', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9209, 23, 13, 'BE', 'Soziales Lernen an allen Schulen verankern, indem Schulen nach dem Vorbild preisgekrönter Schulen fortentwickelt werden.', '{2301}', 9182, 2, 2, null, 'Meta-Analysen zu schulischem sozial-emotionalem Lernen zeigen besseres Klassenklima und weniger Mobbing; ohne festes Programm, Zeitbudget und geschulte Lehrkräfte hängt die Wirkung stark von der Umsetzung ab.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=187', 'https://www.future-ed.org/parsing-the-evidence-on-social-emotional-learnings-impact/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9210, 23, 13, 'BE', 'Projekte gegen Queerfeindlichkeit, Rassismus und Antisemitismus an Schulen ausbauen und fest etablieren, um Akzeptanz und Respekt unter Schülerinnen und Schülern zu fördern.', '{2301}', 9183, 2, 2, null, 'Schulische Anti-Mobbing-Programme senken Mobbing laut Meta-Analysen um rund 20 Prozent, intensive Programme stärker; die Vorschläge nennen meist kein bestimmtes, erprobtes Programm, Wirkung hängt von Auswahl und Umfang ab.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=193', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/school-based-programs-reduce-bullying-and-victimization', 'belegt', '2026-10-08', false, true, 'blind'),
  (9211, 23, 13, 'BE', 'Übergang auf die Oberschule reformieren, damit Kinder der Klassen 4 bis 6 mit weniger Druck zur Schule gehen.', '{2304}', 9190, 1, 3, null, 'Der Übertritt gilt als belastende Phase; weniger Auslese kann den Druck in den Klassen 4 bis 6 senken. Ob Stress messbar sinkt, ist kaum untersucht. Landesrecht, rasch änderbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=188', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9212, 23, 13, 'BE', 'Verlässliche Betreuung bis 14:30 Uhr mit professioneller Begleitung, sodass keine Hausaufgaben zu Hause nötig sind und Hausaufgabenstress entfällt.', '{2304}', null, 1, 2, null, 'Begleitete Lernzeit statt Hausaufgaben kann Stress in Familien senken; die Wirkung auf Leistungsdruck ist kaum untersucht. Längere Betreuung braucht zusätzliches Personal und Geld.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=191', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9213, 23, 13, 'ST', 'Landesaktionsprogramm gegen Mobbing mit Schulklima der Kooperation im Schulgesetz, in Lehrerbildung und Unterricht, Aktionstagen und jährlichem Anti-Mobbing-Tag.', '{2301}', null, 3, 2, null, 'Ein schulweiter Ansatz mit Schulklima, Lehrkräftebildung, Unterricht und Aktionstagen entspricht den Bausteinen, für die Meta-Analysen rund 20 Prozent weniger Mobbing finden; Aufbau landesweit braucht Jahre.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=63', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/school-based-programs-reduce-bullying-and-victimization', 'belegt', '2026-10-08', false, true, 'blind'),
  (9214, 23, 13, 'ST', 'Unabhängige landesweite Ombudsstelle für Diskriminierung und Übergriffe an Schulen mit anonymer Meldung und Beratung.', '{2302}', 9186, 1, 3, null, 'Eine Stelle außerhalb der Schule gibt Betroffenen einen Weg, wenn die Schule nicht handelt; sie greift meist erst spät ein, Wirkungsbelege auf Mobbing fehlen. Rechtlich einfach und mit wenig Personal einrichtbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=64', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9215, 23, 13, 'ST', 'Verbindliche regelmäßige Fortbildungen für Lehrkräfte zu Diskriminierung und Übergriffen.', '{2302}', 9187, 2, 2, null, 'Eine Meta-Analyse findet, dass Programme mit Lehrkräfte-Bausteinen deren Eingreifen spürbar verbessern; kurze Schulungen allein zeigten in einer Studie keine Wirkung. Fortbildungszeit und Vertretung müssen organisiert werden.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=64', 'https://dare.uva.nl/id/b26d9daf-c6d9-4aa1-95e1-ae168727717f', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9216, 23, 13, 'ST', 'Klassenräte und Schülerparlamente als zusätzliche Gremien der Mitbestimmung an Schulen.', '{2301}', 9184, 1, 3, null, 'Regelmäßige Klassenräte können Konflikte früh sichtbar machen und Klassennormen beeinflussen; die Wirkung auf Mobbing ist kaum untersucht, der Schwerpunkt liegt auf Beteiligung. Günstig und rasch einführbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=64', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9217, 23, 13, 'ST', 'Flexible Schuleingangsphase stärken, damit Kinder ohne Leistungsdruck durch Sitzenbleiben Zeit zur Entwicklung haben.', '{2304}', null, 1, 3, null, 'Eine flexible Eingangsphase vermeidet Sitzenbleiben und Stigma in den ersten Jahren; der Leistungsdruck in späteren Klassen bleibt, Wirkung kaum untersucht. Bestehende Modelle lassen sich rasch stärken.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=60', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9218, 23, 14, 'BE', 'Präventive Anti-Gewalt-Trainings im Schulunterricht ausbauen und Polizei, Schulen und Jugendhilfe besser verzahnen.', '{2301}', 9183, 2, 2, null, 'Schulische Anti-Mobbing-Programme senken Mobbing laut Meta-Analysen um rund 20 Prozent, intensive Programme stärker; die Vorschläge nennen meist kein bestimmtes, erprobtes Programm, Wirkung hängt von Auswahl und Umfang ab.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=68', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/school-based-programs-reduce-bullying-and-victimization', 'belegt', '2026-10-08', false, true, 'blind'),
  (9219, 23, 14, 'MV', 'Prävention von Mobbing und Cybermobbing stärken; Lehrkräfte durch Aus- und Fortbildung für Handlungssicherheit qualifizieren', '{2301,2302}', 9183, 2, 2, null, 'Schulische Anti-Mobbing-Programme senken Mobbing laut Meta-Analysen um rund 20 Prozent, intensive Programme stärker; die Vorschläge nennen meist kein bestimmtes, erprobtes Programm, Wirkung hängt von Auswahl und Umfang ab.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=87', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/school-based-programs-reduce-bullying-and-victimization', 'belegt', '2026-10-08', false, true, 'blind'),
  (9220, 23, 14, 'MV', 'Schulordnungen auf klare Regeln konzentrieren; Mobbing mit abgestuften, verbindlichen Reaktionswegen regeln', '{2301}', null, 2, 3, null, 'Klare Schulregeln mit abgestuften, verbindlichen Reaktionen sind Bausteine wirksamer Anti-Mobbing-Programme; ohne Prävention und Begleitung bleibt die Wirkung begrenzt. Schulordnungen sind rasch änderbar.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=89', 'https://www.ojp.gov/index%2Ephp/ncjrs/virtual-library/abstracts/effectiveness-school-based-programs-reduce-bullying-systematic-and', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9221, 23, 14, 'MV', 'Jede Schule erhält eine Kraft für Schulsozialarbeit zur Lösung sozialer Konflikte', '{2302,2301}', 9185, 2, 2, null, 'Fachkräfte vor Ort können bei Konflikten und Mobbing eingreifen und Lehrkräfte entlasten; belastbare Wirkungsstudien zu Mobbing fehlen weitgehend, und Fachkräftemangel sowie Finanzierung bremsen den Ausbau.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=97', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9222, 23, 15, null, 'Rechtliche Sicherheit und Disziplinarrechte von Lehrkräften und Schulen sollen gestärkt werden.', '{2301}', null, 1, 1, null, 'Konsequente Regeln können Normen in der Klasse stützen, harte Disziplin allein ändert sie kaum. Schul- und Ordnungsrecht ist Ländersache, der Bund kann es nicht regeln.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=162', 'https://www.ojp.gov/index%2Ephp/ncjrs/virtual-library/abstracts/effectiveness-school-based-programs-reduce-bullying-systematic-and', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9223, 23, 15, 'BE', 'Übergriffiges Verhalten gegenüber Mitschülern, auch unterhalb der Strafbarkeitsgrenze, soll an Schulen konsequent geahndet werden (Null-Toleranz bei Gewalt).', '{2301}', 9188, 1, 2, null, 'Konsequente Regeln sind in wirksamen Programmen ein Baustein; harte Ausschlüsse allein ändern Klassennormen kaum und verlagern das Problem. Ordnungsrecht ist Landessache, Spezialschulen brauchen Plätze und Personal.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=31', 'https://www.ojp.gov/index%2Ephp/ncjrs/virtual-library/abstracts/effectiveness-school-based-programs-reduce-bullying-systematic-and', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9224, 23, 15, 'MV', 'Schulsozialarbeit wird Landesaufgabe, Zahl der Schulpsychologen wird dem Bedarf angepasst; Gewalt an Schulen soll unterbunden werden.', '{2302}', 9185, 2, 2, null, 'Fachkräfte vor Ort können bei Konflikten und Mobbing eingreifen und Lehrkräfte entlasten; belastbare Wirkungsstudien zu Mobbing fehlen weitgehend, und Fachkräftemangel sowie Finanzierung bremsen den Ausbau.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9225, 23, 15, 'MV', 'Sanktionsmöglichkeiten der Lehrkräfte gesetzlich stärken und bei Gewalt schneller Schulverweise aussprechen.', '{2301}', 9188, 1, 2, null, 'Konsequente Regeln sind in wirksamen Programmen ein Baustein; harte Ausschlüsse allein ändern Klassennormen kaum und verlagern das Problem. Ordnungsrecht ist Landessache, Spezialschulen brauchen Plätze und Personal.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=32', 'https://www.ojp.gov/index%2Ephp/ncjrs/virtual-library/abstracts/effectiveness-school-based-programs-reduce-bullying-systematic-and', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9226, 23, 15, 'ST', 'Schulische Ordnungsmaßnahmen so überarbeiten, dass Gewalttäter schneller der Schule verwiesen und bei Wiederholung an eine Spezialschule überwiesen werden können.', '{2301}', 9188, 1, 2, null, 'Konsequente Regeln sind in wirksamen Programmen ein Baustein; harte Ausschlüsse allein ändern Klassennormen kaum und verlagern das Problem. Ordnungsrecht ist Landessache, Spezialschulen brauchen Plätze und Personal.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=89', 'https://www.ojp.gov/index%2Ephp/ncjrs/virtual-library/abstracts/effectiveness-school-based-programs-reduce-bullying-systematic-and', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9227, 23, 15, 'ST', 'Bei Bedarf einen privaten Wachdienst unter dem Schulleiter einrichten, der auf dem Schulhof gegen Gewalt unter Schülern vorgeht.', '{2302}', null, 1, 2, null, 'Bessere Pausenaufsicht ist in Programmen mit weniger Mobbing verbunden; private Wachleute ohne pädagogischen Auftrag sind dafür kaum untersucht und haben nur Jedermannsrechte. Kosten und Rechtsrahmen sind zu klären.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=88', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9228, 23, 16, 'BE', 'Unabhängige Beschwerdestelle für Schülerinnen, Schüler und Eltern bei Mobbing und Diskriminierung, mit Akteneinsichts- und Durchgriffsrechten.', '{2302}', 9186, 1, 3, null, 'Eine Stelle außerhalb der Schule gibt Betroffenen einen Weg, wenn die Schule nicht handelt; sie greift meist erst spät ein, Wirkungsbelege auf Mobbing fehlen. Rechtlich einfach und mit wenig Personal einrichtbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=162', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9229, 23, 16, 'BE', 'Stelle und Einfluss der Mobbingbeauftragten der Bildungsverwaltung stärken; Beschwerdestrukturen auf Einzelschulebene etablieren.', '{2302}', 9186, 1, 3, null, 'Eine Stelle außerhalb der Schule gibt Betroffenen einen Weg, wenn die Schule nicht handelt; sie greift meist erst spät ein, Wirkungsbelege auf Mobbing fehlen. Rechtlich einfach und mit wenig Personal einrichtbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=162', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9230, 23, 16, 'BE', 'Angebote der Mobbing- und Gewaltprävention für Schulen absichern und verstetigen.', '{2301}', 9183, 2, 2, null, 'Schulische Anti-Mobbing-Programme senken Mobbing laut Meta-Analysen um rund 20 Prozent, intensive Programme stärker; die Vorschläge nennen meist kein bestimmtes, erprobtes Programm, Wirkung hängt von Auswahl und Umfang ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=163', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/school-based-programs-reduce-bullying-and-victimization', 'belegt', '2026-10-08', false, true, 'blind'),
  (9231, 23, 16, 'BE', 'Schulsozialarbeit strukturell stärken, um Ausgrenzung und Gewalt frühzeitig entgegenzuwirken.', '{2301,2302}', 9185, 2, 2, null, 'Fachkräfte vor Ort können bei Konflikten und Mobbing eingreifen und Lehrkräfte entlasten; belastbare Wirkungsstudien zu Mobbing fehlen weitgehend, und Fachkräftemangel sowie Finanzierung bremsen den Ausbau.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=281', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9232, 23, 16, 'BE', 'Ziffernnoten bis Klasse 9 durch Rückmeldungen ersetzen, um Leistungsdruck zu mindern.', '{2304}', 9189, 1, 2, null, 'Weniger Noten kann Bewertungsdruck senken; Studien finden teils weniger Angst, teils kehrt sie zurück, weil Abschlüsse und Übergänge weiter Noten verlangen. Änderung der Schulordnung möglich, verlangt aber Schulung.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=168', 'https://www.timeshighereducation.com/news/gradeless-learning-fails-improve-student-well-being', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9233, 23, 16, 'BE', 'Probeunterricht beim Übergang auf weiterführende Schulen abschaffen, Übergang weniger leistungsbezogen entscheiden.', '{2304}', 9190, 1, 3, null, 'Der Übertritt gilt als belastende Phase; weniger Auslese kann den Druck in den Klassen 4 bis 6 senken. Ob Stress messbar sinkt, ist kaum untersucht. Landesrecht, rasch änderbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=161', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9234, 23, 16, 'BE', 'Psychische Gesundheit im Unterricht und in Projektwochen verankern, um Resilienz zu fördern.', '{2304}', 9191, 1, 3, null, 'Schulische Programme senken Angst und depressive Beschwerden laut Meta-Analysen kurzfristig, die Wirkung lässt aber nach; sie stärken den Umgang mit Druck, senken den Druck selbst nicht. Lehrplanänderung leicht umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=137', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7548227', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9235, 23, 16, 'MV', 'Klassenleiterstunden verbindlich machen und als Klassenrat gemeinsam mit allen Schülern gestalten; Handreichungen für Lehrkräfte.', '{2301}', 9184, 1, 3, null, 'Regelmäßige Klassenräte können Konflikte früh sichtbar machen und Klassennormen beeinflussen; die Wirkung auf Mobbing ist kaum untersucht, der Schwerpunkt liegt auf Beteiligung. Günstig und rasch einführbar.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9236, 23, 16, 'MV', 'Zahl der Klausuren und Tests pro Woche auf höchstens zwei begrenzen.', '{2304}', null, 1, 3, null, 'Eine Obergrenze für Klassenarbeiten kann Prüfungsballungen vermeiden; die Gesamtzahl der Prüfungen und der Notendruck bleiben, Wirkung kaum untersucht. Per Verordnung schnell umsetzbar.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9237, 23, 16, 'MV', 'Resilienzförderung und Lerntrainings in die Rahmenpläne aufnehmen.', '{2304}', 9191, 1, 3, null, 'Schulische Programme senken Angst und depressive Beschwerden laut Meta-Analysen kurzfristig, die Wirkung lässt aber nach; sie stärken den Umgang mit Druck, senken den Druck selbst nicht. Lehrplanänderung leicht umsetzbar.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7548227', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9238, 23, 16, 'ST', 'Bewertung des Verhaltens durch Kopfnoten abschaffen und durch individuelle Rückmeldungen ersetzen.', '{2304}', 9189, 1, 2, null, 'Weniger Noten kann Bewertungsdruck senken; Studien finden teils weniger Angst, teils kehrt sie zurück, weil Abschlüsse und Übergänge weiter Noten verlangen. Änderung der Schulordnung möglich, verlangt aber Schulung.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=30', 'https://www.timeshighereducation.com/news/gradeless-learning-fails-improve-student-well-being', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9239, 23, 17, null, 'Gesetz zur Begrenzung von Social Media für Kinder nach australischem Vorbild', '{2303}', null, 1, 1, null, 'Erste Berichte aus Australien zeigen kaum weniger Nutzung und keinen Rückgang der Beschwerden über Cybermobbing, die Daten sind aber noch kurz. Nationale Altersgrenzen kollidieren mit dem EU-Plattformrecht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', 'https://www.gulf-times.com/article/724968/international/australia/no-meaningful-shift-from-social-media-sites-after-australia-teen-ban-govt-report', 'offen', '2026-10-08', false, true, 'blind'),
  (9240, 23, 17, 'BE', 'Mehr Sozialarbeit an Schulen und flächendeckende Präventions- und Anti-Gewaltprogramme statt reiner Repression.', '{2301,2302}', 9183, 2, 2, null, 'Schulische Anti-Mobbing-Programme senken Mobbing laut Meta-Analysen um rund 20 Prozent, intensive Programme stärker; die Vorschläge nennen meist kein bestimmtes, erprobtes Programm, Wirkung hängt von Auswahl und Umfang ab.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/school-based-programs-reduce-bullying-and-victimization', 'belegt', '2026-10-08', false, true, 'blind'),
  (9241, 23, 17, 'BE', 'Fortbildungsangebote für Lehrkräfte, Sozialarbeiter und Polizei gegen Cybermobbing ausbauen.', '{2302}', 9187, 2, 2, null, 'Eine Meta-Analyse findet, dass Programme mit Lehrkräfte-Bausteinen deren Eingreifen spürbar verbessern; kurze Schulungen allein zeigten in einer Studie keine Wirkung. Fortbildungszeit und Vertretung müssen organisiert werden.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://dare.uva.nl/id/b26d9daf-c6d9-4aa1-95e1-ae168727717f', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9242, 23, 17, 'MV', 'Schulen erhalten multiprofessionelle Teams mit Sozialarbeit, Gesundheitsförderung und Schulpsychologie, um psychischen Problemen und Gewalt vorzubeugen.', '{2302,2301}', 9185, 2, 2, null, 'Fachkräfte vor Ort können bei Konflikten und Mobbing eingreifen und Lehrkräfte entlasten; belastbare Wirkungsstudien zu Mobbing fehlen weitgehend, und Fachkräftemangel sowie Finanzierung bremsen den Ausbau.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9243, 23, 17, 'MV', 'Gewaltschutz, Prävention und soziales Lernen werden als feste Bestandteile schulischer Bildung ausgebaut.', '{2301}', 9182, 2, 2, null, 'Meta-Analysen zu schulischem sozial-emotionalem Lernen zeigen besseres Klassenklima und weniger Mobbing; ohne festes Programm, Zeitbudget und geschulte Lehrkräfte hängt die Wirkung stark von der Umsetzung ab.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', 'https://www.future-ed.org/parsing-the-evidence-on-social-emotional-learnings-impact/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9244, 23, 17, 'ST', 'Längeres gemeinsames Lernen bis zur 8. Klasse, um Überforderung und Leistungsdruck durch frühe Auslese zu verringern.', '{2304}', null, 1, 1, null, 'Spätere Aufteilung kann den Auslesedruck in der Grundschule senken; ob Angst und Stress dadurch sinken, ist kaum untersucht. Umbau der Schulstruktur bis Klasse 8 dauert länger als eine Wahlperiode.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=45', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9245, 23, 18, null, 'Neutrale Schlichtungsstellen helfen bei Konflikten im Schulsystem.', '{2302}', null, 1, 1, null, 'Neutrale Schlichtung kann bei Konflikten mit der Schule helfen; die Wirkung auf Mobbing ist kaum untersucht. Für Schulen sind die Länder zuständig, der Bund kann solche Stellen nicht einrichten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=114', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9246, 23, 18, null, 'Sensibilisierungsprogramme und Mediation gegen Mobbing, vor allem zur Deeskalation von Gewalt in sozialen Medien.', '{2301,2303}', null, 2, 2, null, 'Präventionsprogramme senken Mobbing nachweislich; Arbeit mit Gleichaltrigen ging in einer Meta-Analyse aber mit mehr Opfererfahrungen einher. Schule ist Ländersache, der Bund kann Programme fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=132', 'https://www.ojp.gov/index%2Ephp/ncjrs/virtual-library/abstracts/effectiveness-school-based-programs-reduce-bullying-systematic-and', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9247, 23, 18, null, 'Klassische Noten werden durch ganzheitliche, individuelle Leistungserfassung ersetzt.', '{2304}', null, 1, 1, null, 'Weniger Noten kann Bewertungsdruck senken, die Studienlage ist uneinheitlich. Leistungsbewertung regeln allein die Länder; der Bund kann sie nicht ersetzen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=111', 'https://www.timeshighereducation.com/news/gradeless-learning-fails-improve-student-well-being', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9248, 23, 18, null, 'Resilienzförderung ab dem Kita-Alter, unterstützt durch Weiterbildungen für Lehr- und Fachkräfte.', '{2304}', null, 1, 2, null, 'Resilienzprogramme zeigen kleine, oft kurzlebige Effekte auf Angst; sie stärken den Umgang mit Druck, nicht dessen Ursache. Kita und Schule sind Ländersache, der Bund kann mit Förderprogrammen beitragen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=132', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7548227', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9249, 23, 18, 'BE', 'Empathie und sozial-emotionales Lernen werden fester Unterrichtsbestandteil, im Pflichtfach „Lebenskompetenz“ (zunächst an Pilotschulen), um Mobbing vorzubeugen.', '{2301}', 9182, 2, 2, null, 'Meta-Analysen zu schulischem sozial-emotionalem Lernen zeigen besseres Klassenklima und weniger Mobbing; ohne festes Programm, Zeitbudget und geschulte Lehrkräfte hängt die Wirkung stark von der Umsetzung ab.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=48', 'https://www.future-ed.org/parsing-the-evidence-on-social-emotional-learnings-impact/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9250, 23, 18, 'MV', 'Schulen sollen soziale Kompetenzen und gegenseitiges Verständnis durch klassenübergreifende Projekte, Begegnungstage und verbindliche Beteiligung stärken.', '{2301}', 9182, 2, 2, null, 'Meta-Analysen zu schulischem sozial-emotionalem Lernen zeigen besseres Klassenklima und weniger Mobbing; ohne festes Programm, Zeitbudget und geschulte Lehrkräfte hängt die Wirkung stark von der Umsetzung ab.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=11', 'https://www.future-ed.org/parsing-the-evidence-on-social-emotional-learnings-impact/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9251, 23, 18, 'ST', 'Verbindliche Zeit für Beziehungsarbeit und Klassenentwicklung sowie Unterrichtsformen, die Kooperation statt Konkurrenz fördern.', '{2301}', 9182, 2, 2, null, 'Meta-Analysen zu schulischem sozial-emotionalem Lernen zeigen besseres Klassenklima und weniger Mobbing; ohne festes Programm, Zeitbudget und geschulte Lehrkräfte hängt die Wirkung stark von der Umsetzung ab.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=28', 'https://www.future-ed.org/parsing-the-evidence-on-social-emotional-learnings-impact/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9252, 23, 18, 'ST', 'Klare Konzepte für Stressprävention und Lernbalance an Schulen.', '{2304}', 9191, 1, 3, null, 'Schulische Programme senken Angst und depressive Beschwerden laut Meta-Analysen kurzfristig, die Wirkung lässt aber nach; sie stärken den Umgang mit Druck, senken den Druck selbst nicht. Lehrplanänderung leicht umsetzbar.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=28', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7548227', 'gemischt', '2026-10-08', false, true, 'blind');

